<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A'), state=ref('ready'), selected=ref(0)
const labels=['Throughput','Latency','Uptime'], targets=[75,80,90]
const values=computed(()=>dataset.value==='A'?[82,65,95]:dataset.value==='B'?[70,85,88]:dataset.value==='ties'?targets:[0,0,0])
const directions=['at least','at most','at least']
const meets=(i:number)=>i===1?values.value[i]<=targets[i]:values.value[i]>=targets[i]
const x=(v:number)=>25+v*2.7
function reset(){dataset.value='A';state.value='ready';selected.value=0}
</script>
<template>
<section class="blusage-demo" aria-label="Local bullet chart example"><p>Synthetic normalized scores, not live rates or milliseconds. Bar = value; vertical marker = target. Three neutral background bands show 0–50, 50–80, 80–100, not universal performance grades.</p><div class="blusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="zero">All zero</option><option value="ties">At target</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><div class="blusage-legend"><span>━ Value</span><span>│ Target</span><span>Latency: lower is better</span></div><svg :key="dataset" viewBox="0 0 320 250" role="img" aria-label="Three bullet charts on a fixed zero to one hundred normalized score scale. Exact values, target directions and results are below."><g v-for="(v,i) in values" :key="i" class="blusage-pair" :class="{selected:selected===i}"><text x="25" :y="22+i*65">{{ labels[i] }} · {{ v }} / target {{ targets[i] }}</text><rect v-for="(band,j) in [[0,50],[50,80],[80,100]]" :key="j" class="blusage-band" :x="x(band[0])" :y="32+i*65" :width="(band[1]-band[0])*2.7" height="24" :style="{opacity:.1+j*.1}"/><rect class="blusage-value" x="25" :y="39+i*65" :width="v*2.7" height="10"/><line class="blusage-target" :x1="x(targets[i])" :x2="x(targets[i])" :y1="28+i*65" :y2="60+i*65"/></g><g v-for="tick in [0,50,80,100]" :key="tick"><text :x="x(tick)" y="230" text-anchor="middle">{{ tick }}</text></g><text x="160" y="247" text-anchor="middle">Normalized score · same fixed scale</text></svg><div role="group" aria-label="Select metric" class="blusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @click="selected=i" @focus="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: {{ values[selected] }}, target {{ directions[selected] }} {{ targets[selected] }}. {{ meets(selected)?'Meets target':'Does not meet target' }}.</p><table class="blusage-data"><caption>Exact normalized scores, dataset {{ dataset }}</caption><thead><tr><th scope="col">Metric</th><th scope="col">Value</th><th scope="col">Target</th><th scope="col">Result</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ values[i] }}</td><td>{{ directions[i] }} {{ targets[i] }}</td><td>{{ meets(i)?'Meets':'Misses' }}</td></tr></tbody></table></template><p v-else role="status" class="blusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample metrics in this state. Choose Ready to recover.' }}</p></section>
</template>
